-- Generated by scripts/pricing-to-sql.mjs from lib/pricing-catalog.json (2026-11-pricing-v3).
-- Do not edit by hand: change the catalog and regenerate.

-- Allow flat prices, yearly billing and pricing lines.
alter table public.service_catalog drop constraint if exists service_catalog_billing_interval_check;
alter table public.service_catalog add constraint service_catalog_billing_interval_check
  check (billing_interval in ('one_time', 'month', 'year'));
alter table public.service_catalog drop constraint if exists service_catalog_price_qualifier_check;
alter table public.service_catalog add constraint service_catalog_price_qualifier_check
  check (price_qualifier in ('Starting at', 'Flat'));
alter table public.service_catalog add column if not exists line text;
alter table public.service_catalog drop constraint if exists service_catalog_line_check;
alter table public.service_catalog add constraint service_catalog_line_check
  check (line is null or line in ('starter', 'websites', 'systems', 'presence', 'care'));
alter table public.service_catalog alter column source_ref set default 'lib/pricing-catalog.json';

-- Align legacy slugs with the site and Stripe.
update public.service_catalog set slug = 'google-business-profile-setup'
  where slug = 'google-business-profile-setup-and-verification-support'
  and not exists (select 1 from public.service_catalog where slug = 'google-business-profile-setup');
update public.service_catalog set slug = 'contact-category-location-alignment'
  where slug = 'contact-category-location-and-service-area-alignment'
  and not exists (select 1 from public.service_catalog where slug = 'contact-category-location-alignment');
update public.service_catalog set slug = 'google-workspace-and-business-email'
  where slug = 'google-workspace-and-business-email-setup'
  and not exists (select 1 from public.service_catalog where slug = 'google-workspace-and-business-email');
update public.service_catalog set slug = 'public-data-monitoring-and-alerts'
  where slug = 'public-data-monitoring-and-change-alerts'
  and not exists (select 1 from public.service_catalog where slug = 'public-data-monitoring-and-alerts');

-- Free the unique sort_order values, then upsert the catalog.
update public.service_catalog set sort_order = sort_order + 100000 where sort_order < 100000;

insert into public.service_catalog
  (slug, name, category, line, amount_cents, billing_interval, price_qualifier, scope_note, sort_order, source_ref, active)
values
  ('own-your-bookings', 'Own Your Bookings', 'service', 'starter', 19900, 'one_time', 'Flat', 'Built on the FTD booking and checkout system. Two pages, client-supplied text and photos, one Stripe account. Starter Hosting ($10/month) is required from launch. Stripe processing fees, extra pages and custom design are separate.', 1, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('own-your-bookings-plus', 'Own Your Bookings Plus', 'service', 'starter', 52500, 'one_time', 'Flat', 'Built on the FTD booking and checkout system. Up to four pages, one booking calendar, one Stripe account. Starter Hosting ($10/month) is required from launch. Stripe processing fees are separate. Custom design is a Business Website.', 2, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('shop-bundle', 'Shop Bundle', 'service', 'starter', 84000, 'one_time', 'Starting at', 'Starting scope covers four chairs and one Stripe account for the shop. Starter Hosting ($10/month) is required from launch. Separate Stripe accounts per chair are quoted. Each additional chair is the Shop Bundle Extra Chair item.', 3, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('starter-hosting', 'Starter Hosting', 'service', 'starter', 1000, 'month', 'Flat', 'Required for Own Your Bookings, Own Your Bookings Plus and Shop Bundle, from launch. FTD holds the domain controls while hosting is active. The subscription link is sent with your go-live approval. If you leave, hosting ends and the site comes off FTD servers.', 4, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('starter-get-paid-button', 'Get Paid Button', 'service', 'starter', 9900, 'one_time', 'Flat', 'Retired in pricing v3: Stripe checkout is now included in every Starter Site.', 5, 'lib/pricing-catalog.json@2026-11-pricing-v3', false),
  ('starter-get-found', 'Get Found on Google', 'service', 'starter', 9900, 'one_time', 'Flat', 'Profile claim and basic details for one solo pro. Google controls verification; multi-location and service-area alignment are the business add-ons.', 6, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('starter-pro-inbox', 'Pro Inbox Setup', 'service', 'starter', 6900, 'one_time', 'Flat', 'One mailbox. Google bills its Workspace subscription to the client separately.', 7, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('starter-extra-page', 'Extra Page', 'service', 'starter', 4900, 'one_time', 'Flat', 'One template page with client-supplied text and photos.', 8, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('shop-bundle-extra-chair', 'Shop Bundle Extra Chair', 'service', 'starter', 10500, 'one_time', 'Flat', 'One chair page with its own Book Now button.', 9, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('business-site-essentials', 'Business Site Essentials', 'package', 'websites', 175000, 'one_time', 'Starting at', 'About 14 engineering hours at the $122.50/hour estimating rate. Supplied content, one contact or booking path. Profiles, CRM, and e-commerce are separate.', 10, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('website-launch', 'Website Launch', 'package', 'websites', 385000, 'one_time', 'Starting at', 'Custom mobile-ready marketing site with agreed pages, supplied content, contact path, accessibility and performance checks, and launch QA. Built by the owner-developer, with no agency markup.', 11, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('digital-presence-bundle', 'Digital Presence Bundle', 'package', 'websites', 472500, 'one_time', 'Starting at', 'Website Launch plus a defined set of business-profile setup/alignment tasks. State exact included profiles and business locations.', 12, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('strategic-website-redesign', 'Strategic Website Redesign', 'service', 'websites', 332500, 'one_time', 'Starting at', 'Starting point for a scoped redesign; migration, content writing, complex integrations, and e-commerce priced separately.', 13, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('e-commerce-or-custom-website-features', 'E-commerce or Custom Website Features', 'service', 'websites', 700000, 'one_time', 'Starting at', 'Starting point for custom functionality; payment-provider fees, inventory, tax/shipping setup, and vendor plans excluded.', 14, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('business-website-design-and-development', 'Business Website Design & Development', 'service', 'websites', 550000, 'one_time', 'Starting at', 'Retired 2026-11 pricing v2. Sold as Website Launch.', 15, 'lib/pricing-catalog.json@2026-11-pricing-v3', false),
  ('custom-software-and-automation', 'Custom Software & Automation', 'package', 'systems', 245000, 'one_time', 'Starting at', '20 engineering hours × $122.50/hour. Discovery confirms the feature list; client approves more time before work exceeds the starting allowance.', 16, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('full-business-system', 'Full Business System', 'package', 'systems', 700000, 'one_time', 'Starting at', 'Entry scope is one website plus one defined workflow or integration. Portals, multi-tenant access and multiple integrations are quoted.', 17, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('lead-capture-and-crm-automation', 'Lead Capture & CRM Automation', 'service', 'systems', 98000, 'one_time', 'Starting at', 'One defined lead flow into one CRM, basic notifications, testing, and handoff. CRM licenses, marketing campaigns, and multi-stage automation excluded.', 18, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('api-integration-setup', 'API Integration Setup', 'service', 'systems', 147000, 'one_time', 'Starting at', 'One documented API and one defined data flow. API access approval, vendor fees, rate limits, and work beyond the agreed endpoint/data scope are separate.', 19, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('ai-assistant-or-chatbot-setup', 'AI Assistant / Chatbot Setup', 'service', 'systems', 147000, 'one_time', 'Starting at', 'One bounded use case, approved knowledge sources, safety/fallback behavior, and testing. Model usage, hosting, and content moderation guarantees excluded.', 20, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('clerk-supabase-completion', 'Clerk + Supabase Completion', 'service', 'systems', 245000, 'one_time', 'Starting at', 'Estimate at $122.50/hour, 20 hours. Environment check, defined sign-in/sign-up flow, database access rules for agreed user types, basic flow tests, and handoff.', 21, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('business-analytics-dashboard', 'Business Analytics Dashboard', 'service', 'systems', 245000, 'one_time', 'Starting at', 'One defined dashboard with agreed data sources and measures. Source-system access, paid BI tools, and additional connectors excluded.', 22, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('custom-public-data-collection-tool', 'Custom Public-Data Collection Tool', 'service', 'systems', 245000, 'one_time', 'Starting at', 'Only publicly accessible, permitted data sources or approved APIs. No login bypass, anti-bot evasion, or collection of sensitive personal data.', 23, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('payments-and-back-end-integration', 'Payments & Back-End Integration', 'service', 'presence', 17500, 'one_time', 'Flat', 'Stripe processing fees are separate and paid to Stripe. The existing Stripe product is found by its catalog_slug metadata.', 24, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('yelp-profile-setup-or-cleanup', 'Yelp Profile Setup or Cleanup', 'service', 'presence', 24500, 'one_time', 'Starting at', 'One profile, information cleanup, and handoff. Reviews, ranking, ads, and platform decisions are not guaranteed.', 25, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('apple-business-connect-setup', 'Apple Business Connect Setup', 'service', 'presence', 24500, 'one_time', 'Starting at', 'One business/location setup, subject to Apple account ownership and review.', 26, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('ga4-property-review-audit', 'GA4 Property Review / Audit', 'service', 'presence', 31500, 'one_time', 'Starting at', 'Existing client-owned property required; findings and prioritized fixes. Does not include implementation.', 27, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('google-business-profile-setup', 'Google Business Profile Setup & Verification Support', 'service', 'presence', 36500, 'one_time', 'Starting at', 'Setup and owner-guided verification support; Google controls verification and approval. No guarantee of profile approval or ranking.', 28, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('google-workspace-and-business-email', 'Google Workspace & Business Email Setup', 'service', 'presence', 36500, 'one_time', 'Starting at', 'One domain and agreed mailbox/user configuration. Google subscriptions, migration, and domain charges are separate.', 29, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('contact-category-location-alignment', 'Contact, Category, Location & Service-Area Alignment', 'service', 'presence', 49000, 'one_time', 'Starting at', 'Up to three client-selected profiles; additional locations/platforms quoted separately.', 30, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('ga4-setup-and-validation', 'GA4 Setup & Validation', 'service', 'presence', 64500, 'one_time', 'Starting at', 'New or reset property, measurement plan, agreed events/conversions, validation, and handoff. Custom checkout tracking is separately scoped.', 31, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('website-maintenance-and-support', 'Website Maintenance & Support', 'service', 'care', 12000, 'month', 'Starting at', 'Routine agreed updates, backup checks, basic availability/security checks, and support intake. No included feature-development hours.', 32, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('cloud-management', 'Cloud Management', 'service', 'care', 24500, 'month', 'Starting at', 'Vendor bills, 24/7 monitoring, incident response labor, and remediation are separate unless written into scope.', 33, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('public-data-monitoring-and-alerts', 'Public-Data Monitoring & Change Alerts', 'service', 'care', 24500, 'month', 'Starting at', 'Limited source list and check cadence in writing. Hosting/API/notification fees separate; no change-detection guarantee for third-party sites.', 34, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('developer-change-block', 'Developer Change Block', 'service', 'care', 36500, 'month', 'Starting at', 'Three hours of requested code/content/configuration changes at the $122.50/hour estimating rate. No rollover unless stated in the client agreement.', 35, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('fee-developer-protection', 'Fee Developer Protection', 'service', 'care', 59500, 'month', 'Starting at', 'Protection reduces risk; it does not guarantee security or uninterrupted service.', 36, 'lib/pricing-catalog.json@2026-11-pricing-v3', true),
  ('keep-live', 'Keep-Live', 'service', 'starter', 4200, 'year', 'Flat', 'Retired 2026-11-08: replaced by Starter Hosting ($10/month).', 90, 'lib/pricing-catalog.json@2026-11-pricing-v3', false)
on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  line = excluded.line,
  amount_cents = excluded.amount_cents,
  billing_interval = excluded.billing_interval,
  price_qualifier = excluded.price_qualifier,
  scope_note = excluded.scope_note,
  sort_order = excluded.sort_order,
  source_ref = excluded.source_ref,
  active = excluded.active,
  updated_at = now();

-- Anything no longer in the catalog stops showing.
update public.service_catalog set active = false, updated_at = now()
  where slug not in ('own-your-bookings', 'own-your-bookings-plus', 'shop-bundle', 'starter-hosting', 'starter-get-found', 'starter-pro-inbox', 'starter-extra-page', 'shop-bundle-extra-chair', 'business-site-essentials', 'website-launch', 'digital-presence-bundle', 'strategic-website-redesign', 'e-commerce-or-custom-website-features', 'custom-software-and-automation', 'full-business-system', 'lead-capture-and-crm-automation', 'api-integration-setup', 'ai-assistant-or-chatbot-setup', 'clerk-supabase-completion', 'business-analytics-dashboard', 'custom-public-data-collection-tool', 'payments-and-back-end-integration', 'yelp-profile-setup-or-cleanup', 'apple-business-connect-setup', 'ga4-property-review-audit', 'google-business-profile-setup', 'google-workspace-and-business-email', 'contact-category-location-alignment', 'ga4-setup-and-validation', 'website-maintenance-and-support', 'cloud-management', 'public-data-monitoring-and-alerts', 'developer-change-block', 'fee-developer-protection')
  and active;
